% ----------------------------
% 1) Nyquist plot (visual inspection):
figure; nyquist(G); grid on; title('Nyquist Plot of G(s)');

% 2) Get gain/phase margins (useful guidance):
[Gm,Pm,Wcg,Wcp] = margin(G);
% Display margins (Gm returned as absolute gain factor; Inf => no finite GM)
disp('Gain margin (factor):'); disp(Gm);
disp('Phase margin (deg):'); disp(Pm);
disp('Wcg (rad/s):'); disp(Wcg);
disp('Wcp (rad/s):'); disp(Wcp);

% Interpretation guidance:
