%   sweep test below to find stable Kf ranges.

% 3) Robust (automatable) method: sweep candidate Kf values and test closed-loop stability
Kvec = logspace(-4,4,2000); % sweep over wide range; adjust limits if needed
stableK = [];
for k = Kvec
    CL = feedback(k*G,1); % Gtilde = k*G/(1+k*G)
    if isstable(CL)
        stableK(end+1) = k; %#ok<SAGROW>
    end
end

if isempty(stableK)
    disp('No Kf in the swept range produced a stable closed-loop. Expand sweep or inspect Nyquist.');
else
    % report contiguous stable interval(s) approximately
    Kmin = min(stableK);
    Kmax = max(stableK);
    disp(['Approx stable Kf range found: [', num2str(Kmin), ', ', num2str(Kmax), ']']);
    % pick a conservative Kf in the middle of stable range (geometric mean recommended)
    Kf = sqrt(Kmin*Kmax);
    disp(['Suggested conservative Kf (geometric mean): ', num2str(Kf)]);
end

% Note: If margin(G) gave a finite Gm and the plant has no RHP poles, Kf < Gm is usually safe.
% If the plant has RHP poles or margin gave ambiguous info, rely on the sweep above.

% ----------------------------
