% Use the chosen Kf from above (if stableK empty, choose a candidate and iterate)
if exist('Kf','var')
    G_tilde = feedback(Kf*G,1);
    figure; step(G_tilde); grid on; title(['Step Response of G̃(s) with Kf = ', num2str(Kf)]);
    figure; pzmap(G_tilde); grid on; title(['Pole-Zero Map of G̃(s) with Kf = ', num2str(Kf)]);

